// 1. Variables
const appName = 'Pemula Code';
let score = 0;
score = 10; // OK

// 2. Data Types
const studentName = 'Sari';         // String
const age = 20;                     // Number
const isActive = true;              // Boolean
const skills = ['HTML', 'CSS'];     // Array
const user = { name: 'Sari', age }; // Object

// 3. Checking types
console.log(typeof studentName); // 'string'
console.log(typeof age);         // 'number'
console.log(typeof isActive);    // 'boolean'

// Function declaration with parameters
function calculateTotal(price, taxRate = 0.1) {
  const tax = price * taxRate; // local scope
  return price + tax;
}

// Invoking function with arguments
const total = calculateTotal(100); // 110
console.log(total);

// Block scope example
if (total > 100) {
  const discount = 10; // block scope
  console.log('Discount applied:', discount);
}
